def __init__(self, size: int, device_address: int):
    super().__init__(size)
    self.device_address = device_address

def allocate(self, size: int) -> Any:
    if self._allocate is None:
        raise RuntimeError("PYNQ MMIO/allocator has not been initialized")
    return self._allocate(shape=(size,), dtype="u1")

def sync_to_device(self, buffer: Any) -> None:
    method = getattr(buffer, "sync_to_device", None)
    if callable(method):
        method()
    else:
        flush = getattr(buffer, "flush", None)
        if callable(flush):
            flush()
        else:
            raise RuntimeError("buffer has neither sync_to_device nor flush cache operation")

def sync_from_device(self, buffer: Any) -> None:
    method = getattr(buffer, "sync_from_device", None)
    if callable(method):
        method()
    else:
        invalidate = getattr(buffer, "invalidate", None)
        if callable(invalidate):
            invalidate()
        else:
            raise RuntimeError("buffer has neither sync_from_device nor invalidate cache operation")

def flush(self):
    """Flush the underlying memory if necessary"""
    if not self.coherent:
        self.device.flush(self.bo, self.offset, self.virtual_address, self.nbytes)

def invalidate(self):
    """Invalidate the underlying memory if necessary"""
    if not self.coherent:
        self.device.invalidate(
            self.bo, self.offset, self.virtual_address, self.nbytes
        )

def __init__(cls, name, bases, attrs):
    if "_probe_" in attrs:
        priority = attrs["_probe_priority_"]
        if (
            priority in DeviceMeta._subclasses
            and DeviceMeta._subclasses[priority].__name__ != name
        ):
            raise RuntimeError("Multiple Device subclasses with same priority")
        DeviceMeta._subclasses[priority] = cls
    super().__init__(name, bases, attrs)

def __init__(self, tag, warn=False):
    # Args validation
    if type(tag) is not str:
        raise ValueError("Argument 'tag' must be a string")
    self.tag = tag
    self.parser = None

def __init__(self, device, desc):
    super().__init__(device, desc)
    self._mmio = None

def _xrt_allocate(shape, dtype, device, memidx, cacheable=0, pointer=None, cache=None):
    elements = 1
    try:
        for s in shape:
            elements *= s
    except TypeError:
        elements = shape
    dtype = np.dtype(dtype)
    size = elements * dtype.itemsize
    if pointer is not None:
        bo, buf, device_address = pointer
    else:
        bo = device.allocate_bo(size, memidx, cacheable)
        buf = device.map_bo(bo)
        device_address = device.get_device_address(bo)
    ar = PynqBuffer(
        shape,
        dtype,
        bo=bo,
        device=device,
        buffer=buf,
        device_address=device_address,
        coherent=False,
    )
    if pointer is not None:
        weakref.finalize(buf, _free_bo, device, bo, ar.virtual_address, ar.nbytes)
    if cache is not None:
        ar.pointer = (bo, buf, device_address)
        ar.return_to = cache
    return ar

def __init__(self, device, desc):
    ip_dict = device.ip_dict
    idx = desc["idx"]
    for ip_name, ip in ip_dict.items():
        for stream_name, stream in ip["streams"].items():
            if stream["stream_id"] == idx:
                if stream["direction"] == "output":
                    self.source = ip_name + "." + stream_name
                elif stream["direction"] == "input":
                    self.sink = ip_name + "." + stream_name
    self.source_ip = None
    self.monitors = []
    self.monitor_ips = []
    self.sink_ip = None

def flush(self, bo, offset, ptr, size):
    try:
        bo.sync(pyxrt.xclBOSyncDirection.XCL_BO_SYNC_BO_TO_DEVICE)
    except Exception as e:
        raise RuntimeError(f"Buffer Flush Failed: {str(e)}")

def invalidate(self, bo, offset, ptr, size):
    try:
        bo.sync(pyxrt.xclBOSyncDirection.XCL_BO_SYNC_BO_FROM_DEVICE)
    except Exception as e:
        raise RuntimeError(f"Buffer Invalidate Failed: {str(e)}")
